import { App, Modal } from "obsidian";
import { StrictMode, useState } from "react";
import { createRoot, Root } from "react-dom/client";
import { ColorPicker } from "~/components/RelationshipTypeSettings";
import type { DiscourseRelationType } from "~/types";
import { DEFAULT_TLDRAW_COLOR, type TldrawColorName } from "~/utils/tldrawColors";
import { getRelationTypeErrors } from "~/utils/typeUtils";

type RelationTypeFields = {
  label: string;
  complement: string;
  color: TldrawColorName;
};

type CreateRelationTypeFormProps = {
  relationTypes: DiscourseRelationType[];
  onSubmit: (fields: RelationTypeFields) => Promise<void>;
  onCancel: () => void;
  onCreated: () => void;
};

const CreateRelationTypeForm = ({
  relationTypes,
  onSubmit,
  onCancel,
  onCreated,
}: CreateRelationTypeFormProps) => {
  const [label, setLabel] = useState("");
  const [complement, setComplement] = useState("");
  const [color, setColor] = useState<TldrawColorName>(DEFAULT_TLDRAW_COLOR);
  const [labelError, setLabelError] = useState("");
  const [complementError, setComplementError] = useState("");
  const [submitError, setSubmitError] = useState("");
  const [isSubmitting, setIsSubmitting] = useState(false);

  const handleSubmit = async () => {
    const candidate = { id: "new", label, complement, color, created: 0, modified: 0 };
    const duplicateError =
      getRelationTypeErrors([...relationTypes, candidate])[relationTypes.length] ?? "";
    const nextLabelError = !label
      ? "Label is required"
      : duplicateError.startsWith("Duplicate label")
        ? duplicateError
        : "";
    const nextComplementError = !complement
      ? "Complement is required"
      : duplicateError.startsWith("Duplicate complement")
        ? duplicateError
        : "";
    setLabelError(nextLabelError);
    setComplementError(nextComplementError);
    setSubmitError("");
    if (nextLabelError || nextComplementError) return;

    setIsSubmitting(true);
    try {
      await onSubmit({ label, complement, color });
    } catch {
      setSubmitError("Couldn't save the relation type. Try again.");
      setIsSubmitting(false);
      return;
    }
    onCreated();
  };

  return (
    <form
      className="flex flex-col gap-3"
      onSubmit={(e) => {
        e.preventDefault();
        void handleSubmit();
      }}
    >
      <div>
        <input
          type="text"
          className={`w-full ${labelError ? "input-error" : ""}`}
          placeholder="Label (e.g., supports)"
          value={label}
          onChange={(e) => {
            setLabel(e.target.value);
            setLabelError("");
          }}
          autoFocus
        />
        {labelError && <div className="text-error text-xs">{labelError}</div>}
      </div>
      <div>
        <input
          type="text"
          className={`w-full ${complementError ? "input-error" : ""}`}
          placeholder="Complement (e.g., is supported by)"
          value={complement}
          onChange={(e) => {
            setComplement(e.target.value);
            setComplementError("");
          }}
        />
        {complementError && (
          <div className="text-error text-xs">{complementError}</div>
        )}
      </div>
      <ColorPicker value={color} onChange={setColor} />
      {submitError && <div className="text-error text-xs">{submitError}</div>}
      <div className="modal-button-container mt-2 flex justify-end gap-2">
        <button
          type="button"
          className="mod-normal"
          onClick={onCancel}
          disabled={isSubmitting}
        >
          Cancel
        </button>
        <button type="submit" className="mod-cta" disabled={isSubmitting}>
          Continue
        </button>
      </div>
    </form>
  );
};

type CreateRelationTypeModalProps = {
  relationTypes: DiscourseRelationType[];
  onSubmit: (fields: RelationTypeFields) => Promise<void>;
  onClose: () => void;
};

export class CreateRelationTypeModal extends Modal {
  private root: Root | null = null;
  private props: CreateRelationTypeModalProps;

  constructor(app: App, props: CreateRelationTypeModalProps) {
    super(app);
    this.props = props;
  }

  onOpen() {
    this.setTitle("Add relation type");
    this.root = createRoot(this.contentEl);
    this.root.render(
      <StrictMode>
        <CreateRelationTypeForm
          relationTypes={this.props.relationTypes}
          onSubmit={this.props.onSubmit}
          onCancel={() => this.close()}
          onCreated={() => this.close()}
        />
      </StrictMode>,
    );
  }

  onClose() {
    this.root?.unmount();
    this.root = null;
    this.contentEl.empty();
    this.props.onClose();
  }
}

