// ENG-2256 relation menu empty state + add flyout, driven with real CDP mouse/key input.
const D = "_verify/eng-2256-implement-new-relation-menu-empty-state";
const CANVAS = `${D}/relation-menu-canvas.md`;
const Q = "shape:verify-vqZxA";
const C = "shape:verify-bqu6_";
const E = "shape:verify-4dCoS";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));

export const prepare = async ({ client, json }, cam = { x: 150, y: 150, z: 0.8 }) => {
  await client.evaluate(`return (async () => {
    let leaf = app.workspace.getLeavesOfType("tldraw-dg-preview").find((l) => l.view.file?.path === ${json(CANVAS)});
    if (!leaf) {
      leaf = app.workspace.getLeaf("tab");
      await leaf.setViewState({ type: "tldraw-dg-preview", state: { file: ${json(CANVAS)} } });
    }
    app.workspace.setActiveLeaf(leaf, { focus: true });
    await new Promise((r) => setTimeout(r, 400));
    const el = leaf.view.containerEl.querySelector(".tl-canvas");
    const k = Object.keys(el).find((k) => k.startsWith("__reactFiber"));
    let f = el[k];
    while (f) { const v = f.memoizedProps?.value; if (v?.store && v.getCurrentPageShapes) { window.__dgEd = v; break; } f = f.return; }
    const ed = window.__dgEd;
    ed.deleteShapes(ed.getCurrentPageShapes().filter((s) => s.type === "discourse-relation").map((s) => s.id));
    // Deleting a pending arrow dismisses its menu, which reselects the source node in an effect.
    await new Promise((r) => setTimeout(r, 400));
    ed.selectNone();
    ed.setCamera(${json(cam)});
    if (!window.__dgToastHook) {
      window.__dgToastHook = true;
      document.addEventListener("show-toast", (e) => (window.__dgToasts ??= []).push(e.detail.description ?? e.detail.title));
    }
    window.__dgToasts = [];
    return true;
  })();`);
};

const mouse = (client, type, x, y, extra = {}) =>
  client.send("Input.dispatchMouseEvent", { type, x, y, button: "left", clickCount: 1, ...extra });

const clickAt = async (client, { x, y }) => {
  await mouse(client, "mouseMoved", x, y, { button: "none" });
  await mouse(client, "mousePressed", x, y, { buttons: 1 });
  await mouse(client, "mouseReleased", x, y);
  await sleep(250);
};

// Select `from`, press on the drag dot nearest `to`, move in steps to `to`'s center, release.
export const dragRelation = async ({ client, json }, from, to) => {
  await client.evaluate(`window.__dgEd.select(${json(from)}); return true;`);
  await sleep(300);
  const sel = await client.evaluate(`return window.__dgEd.getSelectedShapeIds();`);
  if (sel.length !== 1 || sel[0] !== from) throw new Error(`expected ${from} selected, got ${sel}`);
  const pts = await client.evaluate(`
    const ed = window.__dgEd;
    const b = ed.getShapePageBounds(${json(to)});
    const target = ed.pageToScreen({ x: b.midX, y: b.midY });
    const dots = [...ed.getContainer().querySelectorAll(".cursor-crosshair")].map((d) => {
      const r = d.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 };
    });
    dots.sort((a, c) => Math.hypot(a.x - target.x, a.y - target.y) - Math.hypot(c.x - target.x, c.y - target.y));
    return { start: dots[0], target, dotCount: dots.length };`);
  if (!pts.start) throw new Error("no drag handle dots rendered");
  const { start, target } = pts;
  await mouse(client, "mouseMoved", start.x, start.y, { button: "none" });
  await mouse(client, "mousePressed", start.x, start.y, { buttons: 1 });
  for (let i = 1; i <= 12; i++) {
    const t = i / 12;
    await mouse(client, "mouseMoved", start.x + (target.x - start.x) * t, start.y + (target.y - start.y) * t, { buttons: 1 });
    await sleep(20);
  }
  await mouse(client, "mouseReleased", target.x, target.y);
  await sleep(400);
  return pts;
};

// Snapshot of the menu, flyout, pending arrow and toasts.
export const observe = ({ client }) =>
  client.evaluate(`
    const ed = window.__dgEd;
    const header = [...document.querySelectorAll("span")].find((s) => s.textContent.trim().toLowerCase() === "relation type");
    const root = header?.closest(".z-30");
    const rect = (el) => { if (!el) return null; const r = el.getBoundingClientRect(); return { l: Math.round(r.left), t: Math.round(r.top), r: Math.round(r.right), b: Math.round(r.bottom), w: Math.round(r.width), h: Math.round(r.height) }; };
    const menu = root?.children[0];
    const flyout = root?.children[1] ?? null;
    const plus = root?.querySelector('[aria-label="Add relation type"]');
    const svg = plus?.querySelector("svg");
    const arrows = ed.getCurrentPageShapes().filter((s) => s.type === "discourse-relation");
    const a = arrows[0];
    const binds = a ? ed.getBindingsFromShape(a.id, "discourse-relation").map((b) => b.props.terminal + ":" + b.toId) : [];
    return {
      menuOpen: !!root,
      menuItems: menu ? [...menu.querySelectorAll(":scope > button")].map((b) => b.textContent.trim()) : [],
      plus: plus ? { expanded: plus.getAttribute("aria-expanded"), hasSvg: !!svg, svgClass: svg?.getAttribute("class"), svgRect: rect(svg), btnRect: rect(plus) } : null,
      headerRect: rect(header?.parentElement),
      menuRect: rect(menu),
      flyout: flyout ? { items: [...flyout.querySelectorAll("button")].map((b) => b.textContent.trim()), rect: rect(flyout) } : null,
      arrowCount: arrows.length,
      arrow: a ? { relationTypeId: a.props.relationTypeId, color: a.props.color, text: a.props.text, bindings: binds, relationInstanceId: a.meta?.relationInstanceId ?? null } : null,
      toasts: window.__dgToasts ?? [],
      selected: ed.getSelectedShapeIds(),
    };`);

const buttonCenter = ({ client, json }, label, where = "any") =>
  client.evaluate(`
    const header = [...document.querySelectorAll("span")].find((s) => s.textContent.trim().toLowerCase() === "relation type");
    const root = header?.closest(".z-30");
    const scope = ${json(where)} === "flyout" ? root?.children[1] : ${json(where)} === "menu" ? root?.children[0] : root;
    const btn = ${json(label)} === "+" ? root?.querySelector('[aria-label="Add relation type"]')
      : [...(scope?.querySelectorAll("button") ?? [])].find((b) => b.textContent.trim() === ${json(label)});
    if (!btn) return null;
    const r = btn.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 };`);

export const clickButton = async (ctx, label, where) => {
  const p = await buttonCenter(ctx, label, where);
  if (!p) throw new Error(`button ${label} (${where}) not found`);
  await clickAt(ctx.client, p);
};

