const send = (method, params = {}) =>
  new Promise((resolve, reject) => {
    const nextId = ++id;
    pending.set(nextId, { resolve, reject });
    ws.send(json({ id: nextId, method, params }));
  });

// Body runs inside a plain function: no top-level await, return a promise chain instead.
const evaluate = async (expression) => {
  const body = /\breturn\b/.test(expression) ? expression : `return (${expression});`;
  const result = await send("Runtime.evaluate", {
    expression: `(() => { ${body} })()`,
    awaitPromise: true,
    returnByValue: true,
  });
  if (result.exceptionDetails) {
    const d = result.exceptionDetails;
    throw new Error(`evaluate failed: ${d.exception?.description ?? d.text}\n${expression}`);
  }
  return result.result.value;
};

const waitFor = async (expression, { timeout = 5000, label } = {}) => {
  const deadline = Date.now() + timeout;
  for (;;) {
    if ((await evaluate(expression).catch(() => false)) === true) return;
    if (Date.now() > deadline) throw new Error(`timeout waiting for ${label ?? expression}`);
    await new Promise((r) => setTimeout(r, POLL_MS));
  }
};

