// ENG-2258 "Create new" relation type dialog, driven with real CDP mouse/key input on the ENG-2256 fixture canvas.
import { prepare, dragRelation, clickButton, observe } from "./base2256.mjs";

const Q = "shape:verify-vqZxA";
const C = "shape:verify-bqu6_";
const E = "shape:verify-4dCoS";
const RIGHT = { x: -150, y: 150, z: 0.8 };
const LABEL = "v2258 informs";
const COMPLEMENT = "v2258 is informed by";
const sleep = (ms) => new Promise((r) => setTimeout(r, ms));
const P = (ctx) => `app.plugins.plugins[${ctx.json(ctx.vault.pluginId)}]`;
const BACKSPACE = { key: "Backspace", code: "Backspace", windowsVirtualKeyCode: 8, nativeVirtualKeyCode: 8 };

const DIALOG = `[...document.querySelectorAll(".modal-container")].find((m) => m.querySelector(".modal-title")?.textContent.trim() === "Add relation type")`;

const dialog = (ctx) =>
  ctx.client.evaluate(`
    const m = ${DIALOG};
    if (!m) return { open: false };
    const inputs = [...m.querySelectorAll("input[type=text]")];
    return {
      open: true,
      placeholders: inputs.map((i) => i.placeholder),
      values: inputs.map((i) => i.value),
      invalid: inputs.map((i) => i.classList.contains("input-error")),
      error: m.querySelector(".text-error")?.textContent.trim() ?? null,
      color: m.querySelector(".relative.min-w-32 > button")?.textContent.replace(/[▲▼]/g, "").trim() ?? null,
      buttons: [...m.querySelectorAll(".modal-button-container button")].map((b) => b.textContent.trim()),
      focused: document.activeElement?.placeholder ?? document.activeElement?.tagName,
    };`);

const centerOf = async (ctx, js) => {
  const p = await ctx.client.evaluate(`const el = (() => { ${js} })(); if (!el) return null; const r = el.getBoundingClientRect(); return { x: r.left + r.width / 2, y: r.top + r.height / 2 };`);
  if (!p) throw new Error(`element not found: ${js}`);
  return p;
};
const clickAt = async (client, { x, y }) => {
  const m = (type, extra = {}) => client.send("Input.dispatchMouseEvent", { type, x, y, button: "left", clickCount: 1, ...extra });
  await m("mouseMoved", { button: "none" });
  await m("mousePressed", { buttons: 1 });
  await m("mouseReleased");
  await sleep(250);
};
const clickEl = async (ctx, js) => clickAt(ctx.client, await centerOf(ctx, js));
const clickInput = (ctx, i) => clickEl(ctx, `return ${DIALOG}?.querySelectorAll("input[type=text]")[${i}];`);
const clickDialogButton = (ctx, text) =>
  clickEl(ctx, `return [...(${DIALOG}?.querySelectorAll("button") ?? [])].find((b) => b.textContent.trim() === ${ctx.json(text)});`);
const colorOption = (ctx, name) =>
  `return [...(${DIALOG}?.querySelectorAll(".relative.min-w-32 > div button") ?? [])].find((b) => b.textContent.trim() === ${ctx.json(name)});`;

const openDialog = async (ctx, where) => {
  await clickButton(ctx, "Create new", where);
  await ctx.client.waitFor(`!!${DIALOG}`, { label: "Add relation type dialog" });
  await sleep(200);
};

// Types into the focused label input, then the complement; picks a colour when given.
const fillDialog = async (ctx, { label, complement, color }) => {
  if (label) {
    await clickInput(ctx, 0);
    await ctx.client.typeText(label);
  }
  if (complement) {
    await clickInput(ctx, 1);
    await ctx.client.typeText(complement);
  }
  if (color) {
    await clickEl(ctx, `return ${DIALOG}?.querySelector(".relative.min-w-32 > button");`);
    await clickEl(ctx, colorOption(ctx, color));
  }
};

const diskSettings = (ctx) =>
  ctx.client.evaluate(`return app.vault.adapter.read(${ctx.json(ctx.vault.pluginDir.replace(ctx.vault.root + "/", "") + "/data.json")}).then((t) => { const d = JSON.parse(t); return { relationTypes: d.relationTypes, discourseRelations: d.discourseRelations }; });`);

const pair = (ctx, from, to) =>
  ctx.client.evaluate(`const ed = window.__dgEd; return { s: ed.getShape(${ctx.json(from)}).props.nodeTypeId, t: ed.getShape(${ctx.json(to)}).props.nodeTypeId };`);

const snapshot = async (ctx) => ({
  relationsJson: await ctx.client.evaluate(`return app.vault.read(app.vault.getAbstractFileByPath("relations.json"));`),
  settings: await ctx.client.evaluate(`const s = ${P(ctx)}.settings; return JSON.stringify({ relationTypes: s.relationTypes, discourseRelations: s.discourseRelations });`),
});
const restore = async (ctx, state) => {
  await ctx.client.clearModals?.();
  await ctx.client.evaluate(`const ed = window.__dgEd; ed?.deleteShapes(ed.getCurrentPageShapes().filter((s) => s.type === "discourse-relation").map((s) => s.id)); return true;`);
  if (!state) return;
  await ctx.client.evaluate(`const p = ${P(ctx)}; Object.assign(p.settings, JSON.parse(${ctx.json(state.settings)})); return p.saveSettings().then(() => true);`);
  await ctx.client.evaluate(`return app.vault.modify(app.vault.getAbstractFileByPath("relations.json"), ${ctx.json(state.relationsJson)}).then(() => true);`);
};

const canvasState = (ctx) =>
  ctx.client.evaluate(`const ed = window.__dgEd; return { shapes: ed.getCurrentPageShapes().length, tool: ed.getCurrentToolId() };`);

export default [
  {
    name: "Empty pair: Create new → dialog → type listed, both toasts, saved",
    input: `drag Question → Claim (no types); Create new; type "${LABEL}x", Backspace, "${COMPLEMENT}", colour Blue; Continue`,
    expected: "dialog titled 'Add relation type' with both placeholders, Black default, Cancel/Continue; typing leaves the canvas alone; colour list is on top; after Continue the dialog closes, the menu lists only the new type, 'Relation type created' + 'Discourse relation added' toasts, data.json has the local type (blue, no status) and a Question→Claim triple",
    setup: snapshot,
    run: async (ctx) => {
      await prepare(ctx);
      await dragRelation(ctx, Q, C);
      const ids = await pair(ctx, Q, C);
      await openDialog(ctx, "menu");
      const opened = await dialog(ctx);
      const menuWhileOpen = await observe(ctx);
      const canvasBefore = await canvasState(ctx);
      await clickInput(ctx, 0);
      await ctx.client.typeText(`${LABEL}x`);
      await ctx.client.key(BACKSPACE);
      await clickInput(ctx, 1);
      await ctx.client.typeText(COMPLEMENT);
      const canvasAfterTyping = await canvasState(ctx);
      await clickEl(ctx, `return ${DIALOG}?.querySelector(".relative.min-w-32 > button");`);
      const onTop = await ctx.client.evaluate(`const b = (() => { ${colorOption(ctx, "Blue")} })(); const r = b.getBoundingClientRect(); return b.contains(document.elementFromPoint(r.left + r.width / 2, r.top + r.height / 2));`);
      await clickEl(ctx, colorOption(ctx, "Blue"));
      const filled = await dialog(ctx);
      await clickDialogButton(ctx, "Continue");
      await ctx.client.waitFor(`!${DIALOG}`, { label: "dialog closed" }).catch(() => {});
      await sleep(600);
      const after = await observe(ctx);
      const disk = await diskSettings(ctx);
      const type = disk.relationTypes.find((rt) => rt.label === LABEL);
      const triple = disk.discourseRelations.filter((r) => r.relationshipTypeId === type?.id);
      return { ids, opened, menuWhileOpen, canvasBefore, canvasAfterTyping, onTop, filled, dialogAfter: await dialog(ctx), after, type, triple };
    },
    expect: (o) => ({
      pass:
        o.opened.open && JSON.stringify(o.opened.placeholders) === JSON.stringify(["Label (e.g., supports)", "Complement (e.g., is supported by)"]) &&
        o.opened.color === "Black" && JSON.stringify(o.opened.buttons) === JSON.stringify(["Cancel", "Continue"]) && o.opened.focused === "Label (e.g., supports)" &&
        o.menuWhileOpen.menuOpen && !o.menuWhileOpen.flyout && o.menuWhileOpen.arrowCount === 1 &&
        o.canvasAfterTyping.shapes === o.canvasBefore.shapes && o.canvasAfterTyping.tool === o.canvasBefore.tool &&
        o.onTop && JSON.stringify(o.filled.values) === JSON.stringify([LABEL, COMPLEMENT]) && o.filled.color === "Blue" &&
        !o.dialogAfter.open && o.after.menuOpen && JSON.stringify(o.after.menuItems) === JSON.stringify([LABEL]) && o.after.arrowCount === 1 && !o.after.arrow.relationTypeId &&
        o.after.toasts.includes("Relation type created") && o.after.toasts.some((t) => t.startsWith(`${LABEL} relation added for `)) &&
        o.type?.id.startsWith("rel_") && o.type.color === "blue" && o.type.complement === COMPLEMENT && !("status" in o.type) &&
        o.triple.length === 1 && o.triple[0].sourceId === o.ids.s && o.triple[0].destinationId === o.ids.t,
      actual: `dialog placeholders=[${o.opened.placeholders}] color=${o.opened.color} buttons=[${o.opened.buttons}] focus=${o.opened.focused}; menu while open=${o.menuWhileOpen.menuOpen} arrows=${o.menuWhileOpen.arrowCount}; canvas ${JSON.stringify(o.canvasBefore)}→${JSON.stringify(o.canvasAfterTyping)}; colour list on top=${o.onTop}; filled=[${o.filled.values}] ${o.filled.color}; after: dialog=${o.dialogAfter.open} menu=[${o.after.menuItems}] toasts=[${o.after.toasts}] type=${JSON.stringify(o.type && { id: o.type.id, color: o.type.color, status: o.type.status })} triples=${JSON.stringify(o.triple.map((r) => r.sourceId + "→" + r.destinationId))}`,
    }),
    teardown: restore,
  },
  {
    name: "Empty pair: created type then creates the relation",
    input: `Question → Claim; Create new "${LABEL}" / "${COMPLEMENT}" / Blue; Continue; click "${LABEL}" in the menu`,
    expected: "arrow gets the new relationTypeId, colour blue and the label as text; menu closes",
    setup: snapshot,
    run: async (ctx) => {
      await prepare(ctx);
      await dragRelation(ctx, Q, C);
      await openDialog(ctx, "menu");
      await fillDialog(ctx, { label: LABEL, complement: COMPLEMENT, color: "Blue" });
      await clickDialogButton(ctx, "Continue");
      await sleep(800);
      await clickButton(ctx, LABEL, "menu");
      await sleep(800);
      const typeId = await ctx.client.evaluate(`return ${P(ctx)}.settings.relationTypes.find((rt) => rt.label === ${ctx.json(LABEL)})?.id;`);
      return { typeId, ...(await observe(ctx)) };
    },
    expect: (o) => ({
      pass: !o.menuOpen && !!o.typeId && o.arrow?.relationTypeId === o.typeId && o.arrow?.color === "blue" && o.arrow?.text === LABEL,
      actual: `menu=${o.menuOpen} arrow type=${o.arrow?.relationTypeId} (want ${o.typeId}) color=${o.arrow?.color} text="${o.arrow?.text}"`,
    }),
    teardown: restore,
  },
  {
    name: "Populated pair: + → Create new works the same",
    input: `drag Evidence → Claim (supports, opposes); +; Create new in the flyout; "${LABEL}" / "${COMPLEMENT}"; Continue`,
    expected: "flyout closes when the dialog opens; after Continue the menu lists the existing types plus the new one, both toasts",
    setup: snapshot,
    run: async (ctx) => {
      await prepare(ctx, RIGHT);
      await dragRelation(ctx, E, C);
      const before = await observe(ctx);
      await clickButton(ctx, "+");
      await openDialog(ctx, "flyout");
      const whileOpen = await observe(ctx);
      await fillDialog(ctx, { label: LABEL, complement: COMPLEMENT });
      await clickDialogButton(ctx, "Continue");
      await sleep(800);
      return { before, whileOpen, after: await observe(ctx), dialog: await dialog(ctx) };
    },
    expect: (o) => ({
      pass: o.whileOpen.menuOpen && !o.whileOpen.flyout && !o.dialog.open &&
        JSON.stringify(o.after.menuItems) === JSON.stringify([...o.before.menuItems, LABEL]) &&
        o.after.toasts.includes("Relation type created") && o.after.toasts.some((t) => t.startsWith(`${LABEL} relation added for `)),
      actual: `before=[${o.before.menuItems}] flyout while open=${!!o.whileOpen.flyout} after=[${o.after.menuItems}] dialog=${o.dialog.open} toasts=[${o.after.toasts}]`,
    }),
    teardown: restore,
  },
  {
    name: "Validation: missing or duplicate fields show an error and save nothing",
    input: "Question → Claim; Create new; Continue empty; label only; existing label 'supports'; new label + existing complement",
    expected: "'Label is required', 'Complement is required', 'Duplicate label \"supports\"', 'Duplicate complement \"…\"'; dialog stays open, inputs marked, no toast, settings unchanged",
    setup: snapshot,
    run: async (ctx, state) => {
      await prepare(ctx);
      await dragRelation(ctx, Q, C);
      const supports = await ctx.client.evaluate(`return ${P(ctx)}.settings.relationTypes.find((rt) => rt.label === "supports");`);
      await openDialog(ctx, "menu");
      const steps = [];
      await clickDialogButton(ctx, "Continue");
      steps.push(await dialog(ctx));
      await fillDialog(ctx, { label: LABEL });
      await clickDialogButton(ctx, "Continue");
      steps.push(await dialog(ctx));
      await fillDialog(ctx, { complement: COMPLEMENT });
      await ctx.client.evaluate(`const i = ${DIALOG}.querySelectorAll("input[type=text]")[0]; i.focus(); i.select(); return true;`);
      await ctx.client.typeText("supports");
      await clickDialogButton(ctx, "Continue");
      steps.push(await dialog(ctx));
      await ctx.client.evaluate(`const i = ${DIALOG}.querySelectorAll("input[type=text]")[0]; i.focus(); i.select(); return true;`);
      await ctx.client.typeText(LABEL);
      await ctx.client.evaluate(`const i = ${DIALOG}.querySelectorAll("input[type=text]")[1]; i.focus(); i.select(); return true;`);
      await ctx.client.typeText(supports.complement);
      await clickDialogButton(ctx, "Continue");
      await sleep(300);
      steps.push(await dialog(ctx));
      const now = await ctx.client.evaluate(`const s = ${P(ctx)}.settings; return JSON.stringify({ relationTypes: s.relationTypes, discourseRelations: s.discourseRelations });`);
      return { steps, supports: supports.complement, unchanged: now === state.settings, toasts: (await observe(ctx)).toasts };
    },
    expect: (o) => {
